head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05501";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05501.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_irDetail.get("isuCd")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_irDetail.get("comNm")); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_irDetail.get("ceoNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_irDetail.get("heldDate")) + " " + String(dma_irDetail.get("heldStartTime")) + " 부터 " + String(dma_irDetail.get("heldEndTime")) + " 까지"; } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_irDetail.get("heldLoc")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(dma_irDetail.get("irChrgNm")); } },
        { childId: "__rb6", attr: "label", fn: function () { return String(dma_irDetail.get("irChrgTelNo")); } },
        { childId: "__rb7", attr: "label", fn: function () { return String(dma_irDetail.get("irChrgEmail")); } },
        { childId: "__rb8", attr: "label", fn: function () { return String(String(dma_irDetail.get("remk")).split(String((dma_pageContext.get("NEW_LINE") ?? ""))).join("")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_closeWin_onclick
 * @description btn_closeWin 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closeWin_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05501.btn_closeWin_onclick' }); }
};
